import{_ as n,o as t,c as i,a2 as s}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Seiten in Flows","description":"Seiten als Oberfläche innerhalb eines Flows anzeigen.","frontmatter":{"title":"Seiten in Flows","description":"Seiten als Oberfläche innerhalb eines Flows anzeigen."},"headers":[],"relativePath":"flows/seiten-in-flows.md","filePath":"flows/seiten-in-flows.md","lastUpdated":1786088669000}'),a={name:"flows/seiten-in-flows.md"};function r(l,e,o,d,c,u){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="seiten-in-flows" tabindex="-1">Seiten in Flows <a class="header-anchor" href="#seiten-in-flows" aria-label="Permalink to &quot;Seiten in Flows&quot;">​</a></h1><p>Ein Flow kann eine <a href="/docs/seiten/was-sind-seiten">Seite</a> anzeigen und auf eine Eingabe warten. Damit werden aus Automatisierungen geführte Prozesse mit Menschen darin — Genehmigungen, Rückfragen, mehrstufige Erfassung.</p><h2 id="die-drei-beteiligten-schritte" tabindex="-1">Die drei beteiligten Schritte <a class="header-anchor" href="#die-drei-beteiligten-schritte" aria-label="Permalink to &quot;Die drei beteiligten Schritte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Schritt</th><th>Rolle</th></tr></thead><tbody><tr><td><strong>Seite anzeigen</strong> (Auslöser)</td><td><em>Flow starten und Seite laden</em></td></tr><tr><td><strong>Seite anzeigen</strong> (Aktion)</td><td><em>Zeigt eine Seite zur Nutzerinteraktion an</em></td></tr><tr><td><strong>Link zu Seite erstellen</strong></td><td><em>Erstellt einen Link zu einer Seite im Flow</em></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Zwei Schritte heißen gleich</p><p>Der <strong>Auslöser</strong> startet den Flow mit einer Seite. Die <strong>Aktion</strong> unterbricht ihn mitten im Ablauf.</p><p>Achten Sie darauf, in welchem Reiter Sie sich befinden — <em>Auslöser</em> oder <em>Aktionen</em>.</p></div><h2 id="seite-als-einstieg" tabindex="-1">Seite als Einstieg <a class="header-anchor" href="#seite-als-einstieg" aria-label="Permalink to &quot;Seite als Einstieg&quot;">​</a></h2><p>Der Auslöser <strong>Seite anzeigen</strong> startet den Flow, sobald jemand eine Seite absendet.</p><p>Die Konfiguration erklärt:</p><blockquote><p><em>Verwende den unten stehenden Link, um die erste Seite unseres Flows zu öffnen. Sobald diese Seite abgesendet wurde, wird der Flow gestartet.</em></p></blockquote><p>Und zur Verteilung:</p><blockquote><p><em>Du kannst diesen Link auch weitergeben, zum Beispiel als QR-Code für einfachen Zugriff oder auf Ihrer Webseite oder im Intranet verlinken.</em></p></blockquote><p><strong>Geeignet für:</strong> Störungsmeldungen, Bestellungen, Anträge — alles, was mit einer Eingabemaske beginnt.</p><h2 id="seite-mitten-im-ablauf" tabindex="-1">Seite mitten im Ablauf <a class="header-anchor" href="#seite-mitten-im-ablauf" aria-label="Permalink to &quot;Seite mitten im Ablauf&quot;">​</a></h2><p>Die Aktion <strong>Seite anzeigen</strong> hält den Flow an. Er läuft weiter, sobald jemand die Seite absendet.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auslöser: Eintrag per Formular</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>E-Mail                   →  „Bitte prüfen&quot;</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Seite anzeigen           →  Flow wartet auf die Freigabe</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Eintrag aktualisieren    →  Status setzen</span></span></code></pre></div><p>Solange gewartet wird, hat die Ausführung im <a href="/docs/flows/durchlaufhistorie">Verlauf</a> den Status <strong>Wartet</strong>.</p><div class="warning custom-block"><p class="custom-block-title">„Seite anzeigen&quot; setzt voraus, dass jemand da ist</p><p>Die Aktion zeigt die Seite der Person, die den Flow gerade bedient. Für jemanden, der erst später Zeit hat, brauchen Sie stattdessen einen Link.</p></div><h2 id="asynchron-uber-einen-link" tabindex="-1">Asynchron über einen Link <a class="header-anchor" href="#asynchron-uber-einen-link" aria-label="Permalink to &quot;Asynchron über einen Link&quot;">​</a></h2><p><strong>Link zu Seite erstellen</strong> erzeugt einen Link auf den laufenden Durchlauf. Diesen verschicken Sie per E-Mail — die Person öffnet ihn, wann es passt.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auslöser: Eintrag wurde geändert   (Status = „Freigabe nötig&quot;)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Link zu Seite erstellen            →  Link auf diesen Durchlauf</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>E-Mail                             →  verschickt den Link</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Seite anzeigen                     →  Flow wartet</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Eintrag aktualisieren</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Der Weg zu echten Genehmigungsprozessen</p><p>Diese Kombination ist der Unterschied zwischen einer Automatisierung, die nur läuft solange jemand zusieht, und einem Prozess, der über Tage funktioniert.</p><p>Die vorgesetzte Person bekommt eine E-Mail, klickt den Link, sieht die Daten, entscheidet — und der Flow läuft weiter.</p></div><h2 id="seite-vorbereiten" tabindex="-1">Seite vorbereiten <a class="header-anchor" href="#seite-vorbereiten" aria-label="Permalink to &quot;Seite vorbereiten&quot;">​</a></h2><p>Eine Seite für einen Flow unterscheidet sich von einem Portal:</p><div class="tip custom-block"><p class="custom-block-title">Nur zeigen, worum es geht</p><ul><li><strong>Kontext anzeigen</strong>: Was soll entschieden werden? Setzen Sie die relevanten Felder auf <em>Nicht änderbar</em>.</li><li><strong>Entscheidung erfassen</strong>: Der Block <strong>Entscheidung</strong> mit eigenen Beschriftungen für Ja und Nein ist hier klarer als ein Häkchen.</li><li><strong>Rückfragen bedingt einblenden</strong>: Bei Ablehnung ein Begründungsfeld — über <a href="/docs/seiten/sichtbarkeit">bedingte Sichtbarkeit</a>.</li><li><strong>Keys vergeben</strong>: Die eingegebenen Werte greifen Sie später über den <strong>Key</strong> des Blocks ab.</li></ul></div><p>→ <a href="/docs/seiten/eingabebloecke">Eingabeblöcke</a> · <a href="/docs/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></p><h2 id="seite-bearbeiten" tabindex="-1">Seite bearbeiten <a class="header-anchor" href="#seite-bearbeiten" aria-label="Permalink to &quot;Seite bearbeiten&quot;">​</a></h2><p>Im Schritt-Editor gibt es den Reiter <strong>Seite bearbeiten</strong> neben <strong>Einstellungen</strong>. Sie müssen also nicht in den Seiten-Bereich wechseln.</p><p>Umgekehrt zeigen die Seiteneinstellungen unter <strong>Verwendung in Flows</strong>, welche Flows eine Seite anzeigen.</p><h2 id="wenn-keine-seite-zugewiesen-ist" tabindex="-1">Wenn keine Seite zugewiesen ist <a class="header-anchor" href="#wenn-keine-seite-zugewiesen-ist" aria-label="Permalink to &quot;Wenn keine Seite zugewiesen ist&quot;">​</a></h2><blockquote><p><em>Für diesen Schritt ist keine eigene UI hinterlegt. Falls du eine UI benötigst, kannst du sie im Flow Editor hinzufügen.</em></p></blockquote><div class="danger custom-block"><p class="custom-block-title">Häufigste Ursache: die Seite wurde gelöscht</p><p>Prüfen Sie vor dem Löschen einer Seite immer den Abschnitt <strong>Verwendung in Flows</strong>. Eine gelöschte Seite bricht jeden Flow, der sie anzeigt — und Betroffene sehen nur <em>Dieser Prozessschritt konnte nicht geladen werden</em>.</p></div><h2 id="testen" tabindex="-1">Testen <a class="header-anchor" href="#testen" aria-label="Permalink to &quot;Testen&quot;">​</a></h2><p>Für flowgebundene Seiten gibt es einen eigenen Testweg: <strong>Mit Daten aus dem Flow Formular</strong> — <em>Das Formular öffnen und mit übermittelten Daten testen</em>.</p><div class="tip custom-block"><p class="custom-block-title">Der realistischste Test</p><p>Andere Testarten setzen künstliche Daten ein. Dieser Weg geht durch die echte Oberfläche und deckt auch Fehler in der Seite selbst auf — fehlende Keys, falsch gesetzte Pflichtfelder, Sichtbarkeitsbedingungen, die nie zutreffen.</p></div><p>→ <a href="/docs/flows/testen">Flows testen</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/flows/trigger">Trigger</a></li><li><a href="/docs/flows/aktionen">Aktionen</a></li><li><a href="/docs/seiten/was-sind-seiten">Was sind Seiten</a></li></ul>`,37)])])}const p=n(a,[["render",r]]);export{g as __pageData,p as default};
